use vstd::prelude::*;

verus! {

/// Specification: given four vectors of equal length `n`,
/// `bmat` returns their concatenation in the order
/// `[top_left, top_right, bottom_left, bottom_right]`.
spec fn vec_len<T>(v: Seq<T>) -> nat {
    v.len()
}

spec fn vec_concat<T>(a: Seq<T>, b: Seq<T>) -> Seq<T> {
    if a.is_empty() {
        b
    } else {
        seq![a.index(0)] + vec_concat(a.subrange(1, a.len()), b)
    }
}

fn bmat(
    top_left: Vec<f32>, 
    top_right: Vec<f32>, 
    bottom_left: Vec<f32>, 
    bottom_right: Vec<f32>
) -> Vec<f32>
    requires
        top_left.len() == top_right.len() &&
        top_left.len() == bottom_left.len() &&
        top_left.len() == bottom_right.len(),
    ensures
        // Same length as sum of inputs
        result.len() == 4 * top_left.len(),
        // Result equals concatenation of inputs in order
        result[..]
            == seq![].to_vec() + 
               top_left.iter().copied().collect::<Vec<f32>>() + 
               top_right.iter().copied().collect::<Vec<f32>>() +
               bottom_left.iter().copied().collect::<Vec<f32>>() +
               bottom_right.iter().copied().collect::<Vec<f32>>(),
{
    let n = top_left.len();
    let mut result = Vec::with_capacity(4 * n);

    // We cannot write pure spec-level assertions about extend in Verus
    // on native Vec<f32>, so we use ensures clause for correctness.

    result.extend(top_left);
    result.extend(top_right);
    result.extend(bottom_left);
    result.extend(bottom_right);

    result
}

}

